/* strucmp/strnucmp for OS-9/68k -- case-insensitive string compare. * * SECAD's alib.l supplies these and it is not here; `dm' calls strucmp to * decide which unarchiver an extension belongs to. Folding is done on a copy * of the character so the caller's string is never touched, and only ASCII * upper case is folded, which is all the callers here compare. */static int fold(c)     int c;{    return (c >= 'A' && c <= 'Z') ? c + ('a' - 'A') : c;}int strucmp(a, b)     register char *a;     register char *b;{    while (*a != '\0' && fold(*a) == fold(*b)) {        a++;        b++;    }    return fold(*a) - fold(*b);}int strnucmp(a, b, n)     register char *a;     register char *b;     int n;{    while (n-- > 0) {        if (fold(*a) != fold(*b))            return fold(*a) - fold(*b);        if (*a == '\0')            return 0;        a++;        b++;    }    return 0;}